const courses = {
  "natural-health": {
    number:"Course 01 · Holistic health", title:"Natural Health Fundamentals", intro:"Build a grounded understanding of hydration, carbohydrates and evidence-informed natural health — then practise using the ideas with care.", image:"assets/course-natural-health.svg", imageAlt:"A young sprout growing from a pot", original:"courses/alive-academy.html",
    teachable:{title:"Water balance is dynamic, not static", copy:["The body continually balances water intake with losses through urine, skin, breath and the digestive tract. Water supports transport, temperature regulation, chemical reactions and the structure of cells.","Hydration needs change with body size, activity, climate, diet, illness and life stage. This is why one fixed intake target cannot describe every person or every day.","Carbohydrate-rich foods also matter in this picture: many fruits, vegetables and cooked grains contribute water, minerals and usable energy alongside carbohydrate."], quote:"A useful health principle is rarely a magic number; it is a pattern interpreted in context."},
    flashcards:[["Osmosis","Movement of water across a selectively permeable membrane toward the side with more dissolved particles."],["Electrolyte","A mineral carrying an electrical charge in body fluids, such as sodium or potassium."],["Activated carbon","A porous filtration material that can adsorb some compounds affecting taste and odour."],["Reverse osmosis","A membrane process using pressure to separate water from many dissolved substances."],["Soluble fibre","Fibre that can form a gel and is fermented to varying degrees by gut microbes."],["Glycaemic response","The change in blood glucose after eating a carbohydrate-containing food or meal."]],
    mnemonic:{word:"WATER",title:"Five cues for a hydration conversation",note:"Use the word as a prompt, not as a diagnostic tool.",items:["Water sources — drinks and water-rich foods","Activity and environment — movement, heat and altitude","Thirst and trends — usual pattern, not one isolated moment","Electrolyte losses — especially with prolonged heavy sweating","Referral signs — symptoms outside nutrition scope"]},
    good:[["Context changes needs","Exercise, heat, fever, pregnancy and some medications can change fluid requirements."],["More is not always better","Excessive water intake can also be harmful, especially when electrolyte balance is disrupted."],["Filtration has trade-offs","Methods vary in what they remove, cost, waste water, maintenance and mineral effects."]],
    practitioner:{intro:"The nutritionist’s role is to listen for patterns, offer practical education within scope and recognize when medical assessment is needed.",steps:["Ask about usual drinks, meals, activity, climate and recent changes.","Look at the whole eating pattern rather than judging a single food or symptom.","Explain options in plain language and agree on one realistic experiment.","Track response over time and refer when symptoms are persistent, severe or unexplained."]},
    caseStudy:{title:"Headaches during a new training routine",scenario:"Maya recently increased her workouts from two to five sessions a week. She reports afternoon headaches and dark urine, and says she drinks very little during work because she dislikes frequent bathroom breaks.",prompt:"What would you ask first, what low-risk education could you offer, and what findings would prompt referral?",answer:"Begin with timing, fluid and food intake, sweat losses, session length, environment, medications and other symptoms. Discuss gradual access to fluids, drinking around activity and monitoring patterns. Do not assume dehydration is the sole cause. Sudden severe headache, neurological symptoms, fainting, persistent vomiting or ongoing symptoms require prompt medical assessment."},
    concepts:[["Fluid balance","Intake and output are continuously regulated; needs vary by circumstance."],["Electrolytes","Charged minerals help support fluid distribution, nerve signals and muscle function."],["Carbohydrate quality","Food structure, fibre, portion and meal context all influence the response."],["Filtration literacy","Match a method to the water concern, evidence, maintenance needs and local guidance."],["Individual context","Age, health, activity, climate and access shape practical recommendations."],["Scope and referral","Nutrition education is not diagnosis; recognize red flags and collaborate appropriately."]],
    practice:[["Name four major roles of water in the body.","Transport, temperature regulation, participation in chemical reactions and maintaining cell/tissue structure are four examples."],["Why can one daily water number be misleading?","Needs shift with body size, activity, environment, diet, health and life stage."],["What is osmosis?","Water movement across a selectively permeable membrane toward a higher concentration of dissolved particles."],["Give two examples of electrolytes.","Sodium and potassium; chloride, calcium and magnesium are other examples."],["How can food contribute to hydration?","Fruits, vegetables, soups, dairy foods and cooked grains can supply meaningful fluid."],["What is the difference between adsorption and absorption?","Adsorption involves substances adhering to a surface; absorption involves entering or being taken into a material."],["Name one strength and one trade-off of reverse osmosis.","It can reduce many dissolved substances, but may waste water and requires maintenance."],["Why does soluble fibre affect a meal’s response?","It can slow gastric emptying and nutrient absorption and may support microbial fermentation."],["What factors shape glycaemic response?","Food form, fibre, preparation, portion, other meal components and individual physiology."],["Why should symptoms be interpreted cautiously?","Many symptoms are non-specific and can have multiple causes beyond nutrition."],["What belongs in a hydration assessment?","Usual fluids and foods, activity, environment, sweat, urine pattern, medications, symptoms and changes over time."],["When should a nutritionist refer?","When symptoms are severe, persistent, unexplained, outside scope or suggest urgent medical risk."]],
    quiz:[{q:"Which best describes osmosis?",o:["Movement of protein into cells","Movement of water across a selective membrane","Breakdown of carbohydrate","Removal of all minerals from water"],a:1,e:"Osmosis refers to water movement across a selectively permeable membrane."},{q:"Which factor can increase fluid needs?",o:["Cool resting conditions","Short sleep alone","Prolonged activity in heat","Reading a textbook"],a:2,e:"Long activity and heat commonly increase sweat loss."},{q:"Activated carbon is primarily known for:",o:["Adsorbing some compounds on its surface","Adding electrolytes","Sterilizing every organism","Producing glucose"],a:0,e:"Its porous surface adsorbs selected compounds; it is not a universal purifier."},{q:"The best first response to a non-specific symptom is to:",o:["Diagnose dehydration","Recommend a supplement immediately","Gather context and screen for referral","Ignore it"],a:2,e:"Context and scope-aware screening come before conclusions."},{q:"A glycaemic response is shaped by:",o:["Carbohydrate grams only","Food and person factors together","Water temperature only","Time of day only"],a:1,e:"Food structure, meal composition and individual physiology all matter."}]},
  "nutrition-studies": {
    number:"Course 02 · Nutrition science", title:"Nutrition: Studies and Applications", intro:"Connect the foundations of nutrients, digestion and metabolism to the way nutrition evidence is interpreted and used.", image:"assets/course-nutrition-studies.svg", imageAlt:"Nutrition science laboratory glassware", original:"courses/nutrition-studies/index.html",
    teachable:{title:"Nutrition is a chain of connected processes",copy:["A food’s nutrients are only the beginning. Digestion breaks food into smaller components, absorption moves available components across the intestinal barrier, and metabolism transforms them for energy, structure, storage or other functions.","Bioavailability describes how much of a consumed nutrient becomes available for the body to use. Food form, nutrient interactions, health status and preparation can all affect it.","Good nutrition reasoning therefore moves from intake, to digestion and absorption, to function — while staying honest about the quality and limits of the evidence."],quote:"What is eaten, what is absorbed and what is used are related — but they are not identical."},
    flashcards:[["Macronutrient","A nutrient needed in relatively large amounts: carbohydrate, fat and protein."],["Micronutrient","A vitamin or mineral required in smaller amounts for normal body processes."],["Digestion","Mechanical and chemical breakdown of food into absorbable components."],["Absorption","Movement of nutrients from the digestive tract into blood or lymph."],["Metabolism","The total set of chemical reactions that sustain life."],["Bioavailability","The proportion of a nutrient that is absorbed and available for use or storage."]],
    mnemonic:{word:"DAME",title:"Follow a nutrient through the body",note:"A simple sequence for explaining what happens after food is eaten.",items:["Digestion — food is broken down","Absorption — components cross into circulation","Metabolism — the body transforms and uses them","Excretion — waste products leave the body"]},
    good:[["Energy is not the whole story","Foods can have similar energy but differ in fibre, micronutrients, structure and satiety."],["Observational is not causal","An association can guide questions, but by itself does not prove that one factor caused another."],["Labels need context","Serving size, ingredients, nutrient amounts and the overall pattern should be read together."]],
    practitioner:{intro:"Translate science without overstating it. A useful recommendation joins evidence, client context, feasibility and respectful follow-up.",steps:["Clarify the client’s question, goals and relevant health context.","Assess the overall pattern, access, culture, preferences and constraints.","Explain the evidence and uncertainty in understandable language.","Co-create a measurable next step and evaluate the result."]},
    caseStudy:{title:"A plant-forward pattern and iron",scenario:"Sam is eating more plant foods and feels proud of the change, but worries after seeing online claims that plant iron is ‘not absorbed.’ Sam asks whether the new pattern is unsafe.",prompt:"How could you explain bioavailability accurately and turn the concern into practical, non-alarmist guidance?",answer:"Acknowledge that non-haem iron absorption is generally more variable than haem iron absorption, but avoid framing plant foods as useless. Review overall intake and relevant risk factors. Pair iron-rich plant foods with vitamin C-rich foods, discuss inhibitors in meal context, and refer for appropriate assessment if symptoms or clinical concerns exist."},
    concepts:[["Nutrient classes","Carbohydrate, fat, protein, vitamins, minerals and water have distinct and overlapping roles."],["Digestion and absorption","Breaking food down is different from moving nutrients into circulation."],["Metabolism","Anabolism builds; catabolism breaks down and releases usable energy."],["Bioavailability","Consumed amount does not automatically equal absorbed or utilized amount."],["Evidence hierarchy","Study design, methods, consistency and applicability shape confidence."],["Application","Recommendations should fit the person, their context and the limits of professional scope."]],
    practice:[["Name the six broad nutrient classes.","Carbohydrate, fat, protein, vitamins, minerals and water."],["What distinguishes a macro- from a micronutrient?","Macronutrients are needed in larger amounts; vitamins and minerals are micronutrients needed in smaller amounts."],["Define digestion.","The mechanical and chemical breakdown of food into smaller, absorbable components."],["Define absorption.","Movement of nutrients across the intestinal barrier into blood or lymph."],["What is metabolism?","The body’s interconnected chemical reactions that build, break down and transform substances."],["Differentiate anabolism and catabolism.","Anabolism builds molecules and requires energy; catabolism breaks molecules down and can release energy."],["What does bioavailability describe?","How much of an ingested nutrient is absorbed and available for use or storage."],["Give two influences on bioavailability.","Food form, preparation, nutrient interactions, health status and life stage are examples."],["Why can’t an observational study prove causation alone?","Confounding, bias and reverse causation may explain an association."],["What makes a nutrition claim more trustworthy?","Appropriate design, transparent methods, replication, effect size and consistency with broader evidence."],["Why is serving size important on a food label?","All listed nutrient amounts are tied to that stated quantity."],["What makes an evidence-based recommendation practical?","It combines credible evidence with goals, culture, access, preferences, safety and follow-up."]],
    quiz:[{q:"Bioavailability refers to:",o:["The price of a food","The amount listed on a label only","The proportion absorbed and available for use","How quickly food is purchased"],a:2,e:"Bioavailability connects intake with absorption and utilization."},{q:"Which process moves nutrients into blood or lymph?",o:["Digestion","Absorption","Excretion","Chewing"],a:1,e:"Absorption moves components across the intestinal barrier."},{q:"Anabolism generally:",o:["Builds larger molecules","Removes all waste","Measures a serving","Proves causation"],a:0,e:"Anabolic pathways build molecules and require energy."},{q:"An observational association:",o:["Always proves causation","Can generate evidence but needs careful interpretation","Is never useful","Replaces all trials"],a:1,e:"It is useful, but confounding and bias must be considered."},{q:"A strong recommendation should include:",o:["Evidence only","Preference only","Evidence, context and follow-up","A universal meal plan"],a:2,e:"Good application integrates science with the individual situation."}]},
  "sports-fitness": {
    number:"Course 03 · Performance", title:"Sports & Fitness Nutrition", intro:"Learn how fuel, fluid and recovery work together — and how to translate performance principles for the individual athlete.", image:"assets/course-sports.svg", imageAlt:"A duotone dumbbell illustration", original:"courses/sports-fitness-nutrition.html",
    teachable:{title:"Performance nutrition starts with the demand",copy:["The body uses all three energy systems, but their relative contribution changes with intensity and duration. Short explosive work relies heavily on rapidly available energy, while longer efforts increasingly depend on oxidative metabolism.","Carbohydrate supports higher-intensity work and replenishes glycogen. Fat is an important fuel, especially at lower intensities and over longer durations. Protein supports tissue repair and adaptation rather than serving as the primary exercise fuel.","The practical question is not ‘Which nutrient is best?’ It is ‘What does this training session demand, and what does this person tolerate?’"],quote:"Fuel the work required, recover from the work completed, and adapt the plan to the athlete."},
    flashcards:[["Glycogen","The stored form of carbohydrate, found mainly in muscle and liver."],["ATP-PC system","A rapid energy system supporting very short, high-power efforts."],["Glycolysis","A pathway that breaks down glucose and can supply energy quickly."],["Oxidative metabolism","Aerobic energy production that supports sustained activity."],["Recovery nutrition","Food and fluid strategies supporting refuelling, repair and rehydration."],["Sweat rate","The approximate amount of fluid lost through sweat per unit of time."]],
    mnemonic:{word:"FUEL",title:"Plan around the session",note:"A quick pre-session and recovery checklist.",items:["Fluids — begin appropriately hydrated","Use carbohydrate — match amount and timing to demand","Enough protein — distribute across the day","Listen and learn — tolerance and response guide adjustment"]},
    good:[["Timing is a tool","Total daily intake is foundational; timing can then support specific training and recovery needs."],["Sweat is individual","Sweat rate and sodium loss vary widely between people and conditions."],["Supplements are secondary","A product should have a clear purpose, evidence, safety review and third-party testing where relevant."]],
    practitioner:{intro:"Start with training demand, daily intake and recovery basics before reaching for specialized products or rigid targets.",steps:["Map the training week: type, duration, intensity, timing and competition priorities.","Review energy intake, carbohydrate availability, protein distribution, fluids and sleep.","Identify the smallest nutrition change likely to improve the priority session.","Monitor performance, recovery, gut comfort and adherence; collaborate or refer as needed."]},
    caseStudy:{title:"The under-fuelled evening runner",scenario:"Jordan runs after work for 75–90 minutes, eats a light lunch, skips an afternoon snack and often feels flat halfway through training. Large pre-run meals cause stomach discomfort.",prompt:"What pattern do you notice, what would you explore, and what practical experiment could be tested?",answer:"The long gap and light intake may leave carbohydrate availability low, but gather details before concluding. Explore total energy intake, lunch, timing, hydration, training intensity and GI history. Test a small, familiar, lower-fibre carbohydrate snack earlier before the run, plus a planned recovery meal. Adjust from tolerance and performance; refer if persistent fatigue or other health concerns appear."},
    concepts:[["Energy systems","ATP-PC, glycolytic and oxidative pathways overlap; intensity and duration shift their contribution."],["Carbohydrate availability","Muscle and liver glycogen help support demanding training."],["Protein distribution","Adequate protein spread across eating occasions supports repair and adaptation."],["Hydration strategy","Plan from individual losses, access, climate and tolerance rather than one rule."],["Recovery","Refuelling, protein, fluid, rest and sleep work as a system."],["Supplement safety","Need, evidence, dose, interactions, contamination risk and sport rules all matter."]],
    practice:[["Why do all three energy systems matter?","They operate together, with relative contribution changing by intensity and duration."],["What is glycogen?","Stored carbohydrate located mainly in muscle and liver."],["Which system dominates a very brief maximal sprint?","The ATP-PC system contributes heavily to the first seconds of explosive work."],["Why is carbohydrate important for intense exercise?","It can supply ATP rapidly and supports higher-intensity work."],["What is protein’s central training role?","Supporting tissue repair, remodelling and adaptation."],["Why is total daily intake foundational?","Timing cannot compensate for consistently inadequate energy or nutrients."],["How can sweat rate be estimated?","Compare pre/post body mass while accounting for fluid intake and urine over a known exercise period."],["Why should hydration plans be individualized?","Losses, climate, intensity, access, acclimation and tolerance vary."],["Name three recovery priorities.","Carbohydrate refuelling, protein for repair, fluid/electrolyte replacement and rest are examples."],["What can reduce pre-exercise gut discomfort?","Test smaller familiar portions, timing, and appropriate fibre/fat choices in training, not competition."],["What should be checked before recommending a supplement?","Purpose, evidence, safety, dose, interactions, third-party testing and governing-body rules."],["What data would you track after changing a fuel plan?","Energy, performance, recovery, GI comfort, hydration indicators and adherence."]],
    quiz:[{q:"Glycogen is stored mainly in:",o:["Muscle and liver","Bone and skin","Lungs only","The stomach"],a:0,e:"Muscle and liver are the main glycogen stores."},{q:"A 6-second maximal effort relies heavily on:",o:["ATP-PC","Oxidative metabolism only","Protein oxidation","Fibre fermentation"],a:0,e:"The ATP-PC system supplies rapid energy for very brief work."},{q:"The first step in a sport nutrition plan is to:",o:["Buy supplements","Understand the training demand and current pattern","Eliminate carbohydrate","Copy another athlete"],a:1,e:"The plan starts with the person and the work required."},{q:"A recovery plan commonly includes:",o:["Only protein","Fuel, protein, fluid and rest","Only electrolytes","Fasting"],a:1,e:"Recovery is multi-factorial."},{q:"A supplement should be considered after reviewing:",o:["Packaging colour","Need, evidence, safety and testing","Social media popularity","Taste alone"],a:1,e:"A clear need and a full safety/evidence screen come first."}]},
  "staying-healthy": {
    number:"Course 04 · Everyday health", title:"Staying Healthy with Nutrition", intro:"Turn nutrition knowledge into flexible, sustainable routines that support health across ordinary days and changing life stages.", image:"assets/course-staying-healthy.svg", imageAlt:"Sun and moon representing a balanced daily rhythm", original:"courses/staying-healthy-nutrition.html",
    teachable:{title:"Patterns matter more than perfect days",copy:["Health-supportive eating is built from repeated choices over time, not from one meal. A varied pattern can provide fibre, protein, essential fats, vitamins, minerals and enjoyable food experiences.","Food quality matters, but so do access, culture, appetite, time, skills and relationships with food. Practical nutrition respects these realities instead of treating eating as a test of willpower.","Small routines — a reliable breakfast, vegetables added to a familiar dinner, or a planned snack — can become anchors that make a broader pattern easier to sustain."],quote:"Consistency is not sameness. It is a dependable direction with room for real life."},
    flashcards:[["Dietary pattern","The overall combination and frequency of foods and drinks consumed over time."],["Nutrient density","The amount of beneficial nutrients a food provides relative to its energy or serving."],["Fibre","Non-digestible carbohydrate components with roles in bowel health, satiety and microbial activity."],["Food variety","Including different foods within and across food groups over time."],["Satiety","The feeling of fullness and reduced desire to eat after a meal."],["Sustainable habit","A behaviour that is realistic enough to repeat in the person’s actual context."]],
    mnemonic:{word:"PLATE",title:"Build a flexible everyday meal",note:"Not every meal must contain every element; use this as an adaptable planning cue.",items:["Plants — add colour and variety","Lean or varied proteins — choose what fits","Adequate energy — eat enough for your needs","Texture and fibre — include satisfying structure","Enjoyment — taste and culture belong"]},
    good:[["Frozen and canned count","Convenient produce can be nutritious, economical and reduce waste; compare added salt or sugar when relevant."],["Variety can be gradual","Rotate one fruit, vegetable, grain or protein at a time rather than rebuilding every meal."],["Health is multi-factorial","Food matters alongside sleep, movement, stress, social connection, healthcare and social conditions."]],
    practitioner:{intro:"Help the client find a repeatable next step that fits their resources and values, without moralizing food or promising certainty.",steps:["Understand routines, culture, budget, cooking access, appetite and the client’s own priorities.","Identify strengths already present in the pattern.","Choose one addition, substitution or planning habit with a clear cue.","Review how it worked, adapt without blame and refer when needs exceed scope."]},
    caseStudy:{title:"Healthy eating in a very busy week",scenario:"Avery works long shifts and relies on takeout most evenings. They want to ‘eat clean’ but feel overwhelmed, dislike meal prep and have a limited grocery budget.",prompt:"How could you reframe the goal and develop one practical, respectful experiment?",answer:"Move away from an all-or-nothing ‘clean’ standard. Ask which meals feel hardest, what equipment and nearby options exist, and what Avery already enjoys. One experiment might be adding a convenient vegetable and a protein-rich item to two familiar takeout meals, or keeping a simple breakfast and snack available. Success is repeatability, not perfection."},
    concepts:[["Overall pattern","Repeated choices across time matter more than a single food or day."],["Variety","Different foods increase the range of nutrients, flavours and experiences."],["Fibre and structure","Whole and minimally processed plant foods can support fullness and digestive health."],["Adequacy","Health-supportive eating includes enough energy and nutrients, not only restriction."],["Food context","Culture, access, skill, time, preference and relationship with food shape feasibility."],["Sustainable change","Specific, small and reviewable steps are more useful than perfectionism."]],
    practice:[["What is a dietary pattern?","The combination, proportion and frequency of foods and drinks consumed over time."],["Why is variety valuable?","It broadens nutrient exposure, flavours, textures and food experiences."],["Define nutrient density.","The beneficial nutrients provided relative to energy or a practical serving."],["Name two roles of fibre.","It can support bowel function, satiety, microbial fermentation and metabolic health."],["Why does adequacy matter in healthy eating?","The body needs sufficient energy and nutrients; health is not simply eating less."],["How can frozen produce support a healthy pattern?","It is convenient, long-lasting and nutritionally useful, often reducing cost and waste."],["What can make a meal more satisfying?","Adequate energy plus protein, fibre, fat, volume, texture and enjoyment can contribute."],["Why avoid labelling food as morally good or bad?","Moral labels can increase guilt and obscure dose, frequency, context and the overall pattern."],["Give one example of an addition-focused goal.","Add a fruit to breakfast or a vegetable to a familiar evening meal."],["What makes a habit sustainable?","It fits the person’s resources, preferences, routine and readiness well enough to repeat."],["Why review a behaviour experiment?","Follow-up shows what helped, what got in the way and how to adapt without blame."],["Name two non-food influences on health.","Sleep, movement, stress, social connection, healthcare, environment and income are examples."]],
    quiz:[{q:"The strongest description of healthy eating is:",o:["A perfect day","A flexible pattern repeated over time","Avoiding all processed food","Using expensive ingredients"],a:1,e:"A sustainable overall pattern matters more than perfection."},{q:"Food variety can help by:",o:["Guaranteeing disease prevention","Broadening nutrient and sensory exposure","Eliminating the need for adequate energy","Making culture irrelevant"],a:1,e:"Variety expands nutrients, flavours and textures."},{q:"Which is an addition-focused goal?",o:["Never eat takeout","Add fruit to three breakfasts this week","Remove every snack","Cook every meal from scratch"],a:1,e:"It is specific, realistic and builds on the current routine."},{q:"Frozen vegetables:",o:["Never count","Can be a nutritious convenient option","Contain no nutrients","Must always be avoided"],a:1,e:"Frozen produce can be highly practical and nutritious."},{q:"A sustainable plan should primarily fit:",o:["An influencer’s routine","The client’s context, values and resources","A rigid universal menu","The most expensive option"],a:1,e:"Fit and repeatability are central to sustainable change."}]}
};

const key = new URLSearchParams(location.search).get("course") || "natural-health";
const course = courses[key] || courses["natural-health"];
const $ = (selector) => document.querySelector(selector);
document.title = `${course.title} · hōlus. study`;
$("#course-number").textContent = course.number;
$("#course-title").textContent = course.title;
$("#course-intro").textContent = course.intro;
$("#course-image").src = course.image;
$("#course-image").alt = course.imageAlt;
$("#original-link").href = course.original;
$("#continue-link").href = course.original;
$("#frame-open-link").href = course.original;
$("#original-frame").src = course.original;
$("#teachable-title").textContent = course.teachable.title;
$("#teachable-copy").innerHTML = course.teachable.copy.map(p=>`<p>${p}</p>`).join("");
$("#teachable-quote").textContent = course.teachable.quote;
$("#flashcard-grid").innerHTML = course.flashcards.map(([front,back],i)=>`<button class="flashcard" type="button" aria-pressed="false"><span class="flashcard-label">Card ${String(i+1).padStart(2,"0")} · tap to reveal</span><span class="front"><strong>${front}</strong></span><span class="back">${back}</span></button>`).join("");
document.querySelectorAll(".flashcard").forEach(card=>card.addEventListener("click",()=>{card.classList.toggle("is-flipped");card.setAttribute("aria-pressed",String(card.classList.contains("is-flipped")));}));
$("#mnemonic-word").textContent = course.mnemonic.word;
$("#mnemonic-title").textContent = course.mnemonic.title;
$("#mnemonic-note").textContent = course.mnemonic.note;
$("#mnemonic-list").innerHTML = course.mnemonic.items.map((item,i)=>`<li><b>${course.mnemonic.word[i]}</b><span>${item}</span></li>`).join("");
$("#good-grid").innerHTML = course.good.map(([title,text])=>`<article class="note-card"><h3>${title}</h3><p>${text}</p></article>`).join("");
$("#practitioner-intro").textContent = course.practitioner.intro;
$("#practitioner-steps").innerHTML = course.practitioner.steps.map(step=>`<li>${step}</li>`).join("");
$("#case-title").textContent = course.caseStudy.title;
$("#case-scenario").textContent = course.caseStudy.scenario;
$("#case-prompt").textContent = course.caseStudy.prompt;
$("#case-answer").textContent = course.caseStudy.answer;
$("#case-reveal").addEventListener("click",()=>{const answer=$("#case-answer");const open=answer.hidden;answer.hidden=!open;$("#case-reveal").setAttribute("aria-expanded",String(open));$("#case-reveal").textContent=open?"Hide the approach":"Reveal a thoughtful approach";});
$("#concept-list").innerHTML = course.concepts.map(([term,definition])=>`<article class="concept-row"><h3>${term}</h3><p>${definition}</p></article>`).join("");
$("#practice-list").innerHTML = course.practice.map(([question,answer])=>`<details class="practice-item"><summary>${question}</summary><div class="practice-answer"><strong>Answer guide:</strong> ${answer}</div></details>`).join("");
$("#quiz-list").innerHTML = course.quiz.map((item,i)=>`<div class="quiz-question"><fieldset><legend>${i+1}. ${item.q}</legend>${item.o.map((option,j)=>`<label class="quiz-option"><input type="radio" name="q${i}" value="${j}"> ${option}</label>`).join("")}</fieldset></div>`).join("");
$("#quiz-form").addEventListener("submit",event=>{event.preventDefault();let score=0;const review=[];course.quiz.forEach((item,i)=>{const chosen=document.querySelector(`input[name="q${i}"]:checked`);if(chosen&&Number(chosen.value)===item.a)score++;else review.push(`<li><strong>Question ${i+1}:</strong> ${item.e}</li>`);});const pct=Math.round(score/course.quiz.length*100);const result=$("#quiz-result");result.innerHTML=`<h3>${score} / ${course.quiz.length} · ${pct}%</h3><p>${pct>=80?"Strong work — the core ideas are taking shape.":pct>=60?"A useful start. Review the explanations and revisit the key concepts.":"Return to the lesson and flashcards, then try again."}</p>${review.length?`<ul>${review.join("")}</ul>`:"<p>You answered every question correctly.</p>"}`;result.hidden=false;result.scrollIntoView({behavior:"smooth",block:"center"});});
